spec.setup_code:
var C={ink:'#04204B',sec:'#3D5F91',guide:'#8098BC',blue:'#0B4FC0',rust:'#B4552F',empty:'#EEF1F6'};
var T=21;
var ST=[0,1.2,3.6,6.0,8.4,10.8,13.2,16.8,18.0,20.0,21.0];
var NAMES=['triangle mult. outgoing','triangle mult. incoming','triangle attention (start)','triangle attention (end)','transition','attention with pair bias','transition'];
var ABBR=['Tri out','Tri in','Attn start','Attn end','MLP','Attn bias','MLP'];
var CAP=[
'One Pairformer block: pair lane z on top, single lane s below, each op adds its output back (residual)',
'1 Triangle multiplication (outgoing): cell (2,5) reads rows 2 and 5 of z',
'2 Triangle multiplication (incoming): cell (2,5) reads columns 2 and 5 of z',
'3 Triangle attention (start): cell (2,5) attends along row 2 (keys, strong); row 5 gives a faint bias',
'4 Triangle attention (end): cell (2,5) attends along column 5 (keys, strong); column 2 gives a faint bias',
'5 Pair transition: cell (2,5) reads only itself (a per-cell MLP)',
'z enters the single track only as an attention bias: one scalar per head per pair',
'Transition on s: each single entry is updated on its own',
'nothing flows back from s to z inside the block',
'Block done: the updated z and s go into the next block'];
var plusT=[];
for(var q=0;q<5;q++)plusT.push(ST[q+1]+0.8*2.4);
plusT.push(ST[6]+0.85*3.6);plusT.push(ST[7]+0.8*1.2);
var seed=7;
function rnd(){seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296;}
var vals=[];
for(var a=0;a<36;a++)vals.push(rnd());
function ss(a,b,x){var t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t);}
function lerp(a,b,t){return a+(b-a)*t;}
function wrap(ctx,text,maxw){
 var words=text.split(' '),lines=[],cur='';
 for(var i=0;i<words.length;i++){
  var test=cur?cur+' '+words[i]:words[i];
  if(cur&&ctx.measureText(test).width>maxw){lines.push(cur);cur=words[i];}else cur=test;
 }
 if(cur)lines.push(cur);
 return lines;
}
function cv(p,i,j){
 if(p==1)return(i==1||i==4)?1:0;
 if(p==2)return(j==1||j==4)?1:0;
 if(p==3)return i==1?1:(i==4?2:0);
 if(p==4)return j==4?1:(j==1?2:0);
 if(p==5)return(i==1&&j==4)?1:0;
 if(p==6)return 2;
 return 0;
}
return {draw:function(ctx,W,H,time,dt){
 ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);
 ctx.setLineDash([]);ctx.globalAlpha=1;
 var cyc=Math.floor(time/T),t=time%T;
 var p=0;while(p<9&&t>=ST[p+1])p++;
 var dur=ST[p+1]-ST[p],ts=t-ST[p],u=ts/dur;
 var pY=H*0.28,sY=H*0.54;
 var xs=66,xe=W-10,s=(xe-xs-30)/7;
 function sl(k){return xs+8+s*k;}
 function cx(k){return sl(k)+s*0.5;}
 var bw=s*0.66,bh=44,mode=bw>=66?2:(bw>=44?1:0);
 ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillStyle=C.ink;
 var ca=Math.min(ss(0,0.3,ts),1-ss(dur-0.3,dur,ts));
 ctx.globalAlpha=ca;
 var cl=wrap(ctx,CAP[p],W-16);
 for(var i=0;i<cl.length;i++)ctx.fillText(cl[i],W/2,18+i*15);
 ctx.globalAlpha=1;
 ctx.lineWidth=2;
 var lanes=[[pY,C.blue],[sY,C.rust]];
 for(var l=0;l<2;l++){
  var ly=lanes[l][0];ctx.strokeStyle=lanes[l][1];ctx.fillStyle=lanes[l][1];
  ctx.beginPath();ctx.moveTo(xs,ly);ctx.lineTo(xe-4,ly);ctx.stroke();
  ctx.beginPath();ctx.moveTo(xe,ly);ctx.lineTo(xe-7,ly-4);ctx.lineTo(xe-7,ly+4);ctx.closePath();ctx.fill();
 }
 ctx.textAlign='left';
 ctx.fillStyle=C.blue;ctx.fillText('pair z (N x N x 128)',10,pY+40);
 ctx.fillStyle=C.rust;ctx.fillText('single s (N x 384)',10,sY+40);
 var pp=0;
 for(var k=0;k<5;k++)if(t>=plusT[k])pp=Math.max(pp,Math.exp(-(t-plusT[k])*2.5));
 for(var i=0;i<6;i++)for(var j=0;j<6;j++){
  var gx0=10+j*8,gy0=pY-24+i*8;
  ctx.fillStyle=C.empty;ctx.fillRect(gx0,gy0,7,7);
  ctx.fillStyle=C.blue;ctx.globalAlpha=Math.min(1,0.15+0.25*vals[i*6+j]+pp*0.55);
  ctx.fillRect(gx0,gy0,7,7);ctx.globalAlpha=1;
 }
 var sf=0;
 if(p==6)sf=ss(0.55,0.7,u)*(1-ss(0.85,1,u));
 for(var k=5;k<7;k++)if(t>=plusT[k])sf=Math.max(sf,Math.exp(-(t-plusT[k])*2.5));
 for(var i=0;i<6;i++){
  ctx.fillStyle=C.empty;ctx.fillRect(30,sY-24+i*8,7,7);
  ctx.fillStyle=C.rust;ctx.globalAlpha=Math.min(1,0.15+0.2*vals[i]+sf*0.65);
  ctx.fillRect(30,sY-24+i*8,7,7);ctx.globalAlpha=1;
 }
 if(sf>0.05){ctx.strokeStyle=C.rust;ctx.globalAlpha=sf;ctx.lineWidth=2;ctx.strokeRect(27,sY-27,13,54);ctx.globalAlpha=1;}
 var pr=Math.min(5,s*0.09);
 for(var k=0;k<7;k++){
  var lane=k<5?pY:sY,col=k<5?C.blue:C.rust,c=cx(k),L=c-bw/2,R=c+bw/2,mid=lane-26;
  var act=0;
  if(k<5&&p==k+1)act=ss(0.12,0.3,u)*(1-ss(0.7,0.88,u));
  if(k==5&&p==6)act=ss(0.5,0.62,u)*(1-ss(0.85,0.98,u));
  if(k==6&&p==7)act=ss(0.12,0.3,u)*(1-ss(0.7,0.88,u));
  ctx.strokeStyle=col;ctx.lineWidth=1.5;
  ctx.beginPath();ctx.moveTo(c-0.4*s,lane);ctx.lineTo(c-0.4*s,mid);ctx.lineTo(L,mid);
  ctx.moveTo(R,mid);ctx.lineTo(c+0.4*s,mid);ctx.lineTo(c+0.4*s,lane-pr);ctx.stroke();
  ctx.fillStyle='#ffffff';ctx.fillRect(L,mid-bh/2,bw,bh);
  ctx.fillStyle=col;ctx.globalAlpha=0.2*act;ctx.fillRect(L,mid-bh/2,bw,bh);ctx.globalAlpha=1;
  ctx.strokeStyle=act>0.3?col:C.ink;ctx.lineWidth=1+act;ctx.strokeRect(L,mid-bh/2,bw,bh);
  ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillStyle=C.ink;
  var lines=mode==2?wrap(ctx,NAMES[k],bw-6):(mode==1?wrap(ctx,ABBR[k],bw-4):[String(k+1)]);
  for(var i=0;i<lines.length;i++)ctx.fillText(lines[i],c,mid-(lines.length-1)*6+i*12+4);
  var pl=0;if(t>=plusT[k])pl=Math.exp(-(t-plusT[k])*2.5);
  var px=c+0.4*s;
  ctx.beginPath();ctx.arc(px,lane,pr+pl*3,0,6.2832);ctx.fillStyle='#ffffff';ctx.fill();
  ctx.fillStyle=col;ctx.globalAlpha=0.5*pl;ctx.fill();ctx.globalAlpha=1;
  ctx.strokeStyle=col;ctx.lineWidth=1.5;ctx.stroke();
  ctx.beginPath();ctx.moveTo(px-pr*0.6,lane);ctx.lineTo(px+pr*0.6,lane);ctx.moveTo(px,lane-pr*0.6);ctx.lineTo(px,lane+pr*0.6);ctx.stroke();
 }
 var da=0,dx=cx(5),yEnd=sY-48;
 if(p==6)da=ss(0.05,0.4,u);
 if(p==7)da=1;
 var daA=p==7?1-ss(0,0.8,u):1;
 if(da>0.01){
  ctx.globalAlpha=daA;ctx.strokeStyle=C.blue;ctx.fillStyle=C.blue;ctx.lineWidth=2.5;
  var ye=pY+(yEnd-pY)*da;
  ctx.beginPath();ctx.moveTo(dx,pY);ctx.lineTo(dx,ye);ctx.stroke();
  if(da>0.95){ctx.beginPath();ctx.moveTo(dx,yEnd+1);ctx.lineTo(dx-5,yEnd-8);ctx.lineTo(dx+5,yEnd-8);ctx.closePath();ctx.fill();}
  ctx.font='11px sans-serif';ctx.textAlign='left';
  ctx.fillText('bias b_ij',dx+7,pY+(yEnd-pY)*0.5+4);
  ctx.globalAlpha=1;
 }
 var xa=0,xx=xe-14;
 if(p==8)xa=ss(0.1,0.5,u);
 if(p==9)xa=1-ss(0,0.5,u);
 if(xa>0.01){
  var yt=pY+10,yb=sY-2,ye2=yb+(yt-yb)*(p==8?xa:1);
  ctx.globalAlpha=p==9?xa:1;
  ctx.strokeStyle=C.guide;ctx.fillStyle=C.guide;ctx.lineWidth=2.5;ctx.setLineDash([5,4]);
  ctx.beginPath();ctx.moveTo(xx,yb);ctx.lineTo(xx,ye2);ctx.stroke();ctx.setLineDash([]);
  if(p==9||xa>0.95){ctx.beginPath();ctx.moveTo(xx,yt-3);ctx.lineTo(xx-5,yt+7);ctx.lineTo(xx+5,yt+7);ctx.closePath();ctx.fill();}
  var my=(yt+yb)/2,xo=p==8?ss(0.5,0.7,u):1;
  if(xo>0.01){
   ctx.globalAlpha=(p==9?xa:1)*xo;ctx.strokeStyle=C.sec;ctx.lineWidth=3;
   ctx.beginPath();ctx.moveTo(xx-8,my-8);ctx.lineTo(xx+8,my+8);ctx.moveTo(xx+8,my-8);ctx.lineTo(xx-8,my+8);ctx.stroke();
   ctx.font='11px sans-serif';ctx.textAlign='right';ctx.fillStyle=C.sec;
   ctx.fillText('no s → z',xx-14,my-6);
  }
  ctx.globalAlpha=1;
 }
 var ia=0;
 if(p>=1&&p<=5)ia=ss(0.12,0.3,u)*(1-ss(0.7,0.88,u));
 if(p==6)ia=ss(0.05,0.2,u)*(1-ss(0.45,0.6,u));
 if(ia>0.01){
  var c2=14,gx=W/2-3*c2-40,gy=H*0.70;
  ctx.globalAlpha=ia;
  ctx.font='12px sans-serif';ctx.textAlign='left';ctx.fillStyle=C.ink;
  var ttl=p<=5?(p+' · '+NAMES[p-1]):'z → bias per head';
  ctx.fillText(ttl,Math.max(10,gx),gy-9);
  for(var i=0;i<6;i++)for(var j=0;j<6;j++){
   var v=cv(p,i,j),x0=gx+j*c2,y0=gy+i*c2;
   ctx.fillStyle=C.empty;ctx.fillRect(x0,y0,c2-1,c2-1);
   if(v>0){ctx.fillStyle=v==1?'rgba(11,79,192,0.85)':'rgba(11,79,192,0.3)';ctx.fillRect(x0,y0,c2-1,c2-1);}
   if(i==1&&j==4){ctx.fillStyle=C.rust;ctx.fillRect(x0,y0,c2-1,c2-1);ctx.strokeStyle=C.ink;ctx.lineWidth=1.5;ctx.strokeRect(x0,y0,c2-1,c2-1);}
  }
  var lx=gx+6*c2+12;
  ctx.font='11px sans-serif';
  var leg=[[C.rust,'target (i,j) = (2,5)'],['rgba(11,79,192,0.85)','read, strong'],['rgba(11,79,192,0.3)','read, faint (bias)']];
  for(var i=0;i<3;i++){
   ctx.fillStyle=leg[i][0];ctx.fillRect(lx,gy+i*18,10,10);
   ctx.fillStyle=C.ink;ctx.fillText(leg[i][1],lx+15,gy+i*18+9);
  }
  ctx.fillStyle=C.sec;ctx.fillText('rows = i, columns = j',lx,gy+3*18+9);
  ctx.globalAlpha=1;
 }
 var dxp=sl(0),dyp=pY,da2=0,m=0;
 if(p==0){dxp=sl(0);dyp=pY;da2=ss(0.3,1,u);}
 else if(p>=1&&p<=5){
  var kk=p-1,bb=ss(0.12,0.3,u)*(1-ss(0.7,0.88,u));
  dxp=sl(kk)+s*u*u*(3-2*u);dyp=pY-26*bb;da2=1;
 }else if(p==6){
  var a1=ss(0,0.3,u),b1=ss(0.3,0.6,u),c1=ss(0.65,1,u);
  dxp=lerp(sl(5),cx(5),a1)+(sl(6)-cx(5))*c1;
  dyp=lerp(pY,sY-26,b1);
  dyp=dyp+(sY-dyp)*ss(0.85,1,u)*(c1>0?1:0);
  m=b1;da2=1;
 }else if(p==7){
  var bb7=ss(0.12,0.3,u)*(1-ss(0.7,0.88,u));
  dxp=sl(6)+s*u*u*(3-2*u);dyp=sY-26*bb7;m=1;da2=1;
 }else if(p==8){
  dxp=sl(7)+12*ss(0,0.5,u);dyp=sY;m=1;da2=1-ss(0,0.4,u);
 }
 if(da2>0.01){
  var cols=[[C.blue,1-m],[C.rust,m]];
  for(var q2=0;q2<2;q2++){
   var al=cols[q2][1]*da2;if(al<0.01)continue;
   ctx.fillStyle=cols[q2][0];
   ctx.globalAlpha=0.2*al;ctx.beginPath();ctx.arc(dxp,dyp,11,0,6.2832);ctx.fill();
   ctx.globalAlpha=al;ctx.beginPath();ctx.arc(dxp,dyp,5.5,0,6.2832);ctx.fill();
  }
  ctx.globalAlpha=da2;ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;
  ctx.beginPath();ctx.arc(dxp,dyp,5.5,0,6.2832);ctx.stroke();ctx.globalAlpha=1;
 }
 var kc=1+(cyc+(p==9?1:0))%48;
 ctx.font='13px sans-serif';ctx.textAlign='center';
 ctx.fillStyle=p==9?C.rust:C.ink;
 ctx.fillText(kc+' of 48 blocks',W/2,H-12);
 ctx.globalAlpha=1;
}};
